  "implementation": "import json

def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    distances = case['distances']

    if not nodes:
        return {'mst_edges': [], 'total_weight': 0.0}

    n = len(nodes)
    node_to_idx = {node: i for i, node in enumerate(nodes)}

    # Build mutual reachability edges
    edges = []
    for u, v, d in distances:
        if u not in node_to_idx or v not in node_to_idx:
            raise ValueError(f"Unknown node in distance pair: {u}, {v}")
        # Canonicalize endpoints (lexicographic order)
        if u > v:
            u, v = v, u
        w = max(core[u], core[v], d)
        edges.append((w, u, v))

    # Sort by weight, then first endpoint, then second endpoint
    edges.sort(key=lambda x: (x[0], x[1], x[2]))

    # Union-Find
    parent = list(range(n))
    rank = [0] * n

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        xr = find(x)
        yr = find(y)
        if xr == yr:
            return False
        if rank[xr] < rank[yr]:
            xr, yr = yr, xr
        parent[yr] = xr
        if rank[xr] == rank[yr]:
            rank[xr] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    for w, u, v in edges:
        if len(mst_edges) == n - 1:
            break
        if union(node_to_idx[u], node_to_idx[v]):
            mst_edges.append([u, v, w])
            total_weight += w

    if len(mst_edges) != n - 1:
        raise ValueError("Graph is disconnected; cannot form a spanning tree")

    return {
        'mst_edges': mst_edges,
        'total_weight': total_weight
    }
